import { Worker } from 'node:worker_threads';
import { NotLeaderError, RejectedError } from './errors.mjs';
import { registerWorker } from './workerRegistry.mjs';

function normalizeWorkerApply(raw) {
  if (!raw) return null;
  if (typeof raw === 'string') return { module: raw };
  if (typeof raw !== 'object') {
    throw new Error('workerApply must be a string or object');
  }
  if (!raw.module || typeof raw.module !== 'string') {
    throw new Error('workerApply.module must be a string');
  }
  return {
    module: raw.module,
    export: raw.export,
    options: raw.options,
  };
}

function normalizeWorkerStorage(raw) {
  if (!raw) return null;
  if (typeof raw === 'string') return { kind: raw };
  if (typeof raw !== 'object') {
    throw new Error('workerStorage must be a string or object');
  }
  return { ...raw };
}

/**
 * ThreadedRaftNode
 * - Runs the Raft core (WASM wrapper + storage + tick/drain loop) inside a worker thread.
 * - Keeps transport and application logic (apply) on the main thread by default.
 * - Optional: run apply() and storage inside the worker via workerApply/workerStorage.
 *
 * Public API mirrors RaftNode:
 *  - start(), stop(), status(), propose(data), step(msg), campaign()
 *
 * How it works:
 *  - Main thread spawns ./raft-worker.mjs (worker thread).
 *  - Main sends RPC requests; worker responds with { type: 'response', reqId, result|error }.
 *  - Worker emits:
 *      - { type: 'outbound', fromId, msgs } -> main calls transport.send(id, msgs)
 *      - { type: 'applyCommitted', reqId, entries } -> main applies entries then replies { type: 'applyAck', reqId }
 */
export class ThreadedRaftNode {
  /**
   * @param {Object} opts
   * @param {string} opts.id
   * @param {string[]} [opts.peers]
   * @param {number} opts.electionTick
   * @param {number} opts.heartbeatTick
   * @param {{ send(fromId: string, msgs: any[]): Promise<void>, register?: (node: ThreadedRaftNode) => void }} opts.transport
   * @param {(entry: any) => Promise<void>|void} [opts.apply]
   * @param {number} [opts.tickIntervalMs]
   * @param {boolean} [opts.preVote]
   * @param {boolean} [opts.checkQuorum]
   * @param {boolean} [opts.debug]
   * @param {{ module: string, export?: string, options?: any } | string} [opts.workerApply]
   * @param {{ kind?: string, module?: string, export?: string, options?: any } | string} [opts.workerStorage]
   * @param {'main'|'worker'} [opts.applyMode]
   */
  constructor(opts) {
    this.id = String(opts.id);
    this.peers = Array.isArray(opts.peers) ? opts.peers.map(String) : [this.id];
    this.electionTick = Number(opts.electionTick);
    this.heartbeatTick = Number(opts.heartbeatTick);
    this.transport = opts.transport;
    this.apply = opts.apply;
    this.tickIntervalMs = opts.tickIntervalMs ?? 100;
    this.preVote = !!opts.preVote;
    this.checkQuorum = !!opts.checkQuorum;
    this.debug = !!opts.debug;
    this.metrics = opts.metrics || null;
    this.workerApply = normalizeWorkerApply(opts.workerApply);
    this.workerStorage = normalizeWorkerStorage(opts.workerStorage);
    const requestedApplyMode = opts.applyMode;
    this.applyMode = this.workerApply ? 'worker' : (requestedApplyMode || 'main');
    this._applyInWorker = this.applyMode === 'worker';

    if (requestedApplyMode && requestedApplyMode !== this.applyMode) {
      throw new Error(`applyMode "${requestedApplyMode}" conflicts with workerApply configuration`);
    }
    if (this._applyInWorker && !this.workerApply) {
      throw new Error('applyMode "worker" requires workerApply configuration');
    }
    if (!this._applyInWorker) {
      if (typeof this.apply !== 'function') {
        throw new Error('apply(entry) handler is required');
      }
    } else if (this.apply != null && typeof this.apply !== 'function') {
      throw new Error('apply(entry) must be a function when provided');
    }
    if (!this.transport || typeof this.transport.send !== 'function') {
      throw new Error('transport.send(fromId, msgs) is required');
    }

    this._worker = null;
    this._running = false;

    // RPC tracking
    this._nextReqId = 1;
    this._pending = new Map(); // reqId -> { resolve, reject }

    // Bind message handler
    this._onMessage = this._onMessage.bind(this);
    this._onWorkerError = this._onWorkerError.bind(this);
    this._onWorkerExit = this._onWorkerExit.bind(this);

    // Leadership/status cache (updated from worker 'stateUpdate')
    this._role = 'unknown';
    this._term = 0;
    this._lead = null;
    this._commitIndex = 0;
    this._lastApplied = 0;
    this._lastLogIndex = 0;

    // Event listeners
    this._stateChangeCbs = new Set();
    this._becameLeaderCbs = new Set();
    this._becameFollowerCbs = new Set();

    // Waiters for commit/apply indexes
    this._commitWaiters = new Set();
    this._applyWaiters = new Set();
    // One-shot drain waiters (resolved when worker reports drain)
    this._drainWaiters = new Set();

    // Additional event channels
    this._roleChangeCbs = new Set();
    this._commitAdvancedCbs = new Set();
    this._quorumActiveCbs = new Set();

    // Quorum/lease tracking
    this._lastQuorumActiveTerm = 0;

    // Optional residency tick counter (incremented on drain while leader)
    this._termResidencyTicks = 0;

    // Apply reentrancy guard
    this._isApplying = false;
  }

  // Transport entry point: allow InMemoryTransport to route messages to us.
  async step(msg) {
    if (!this._running) return;
    await this._request('step', { message: msg });
  }

  async start() {
    if (this._running) return;

    // Spawn the worker with ESM module support
    this._worker = new Worker(new URL('./raft-worker.mjs', import.meta.url), { type: 'module' });
    registerWorker(this._worker);
    this._worker.on('message', this._onMessage);
    this._worker.on('error', this._onWorkerError);
    this._worker.on('exit', this._onWorkerExit);

    // Initialize the worker-side node with our config
    await this._request('init', {
      id: this.id,
      peers: this.peers,
      electionTick: this.electionTick,
      heartbeatTick: this.heartbeatTick,
      preVote: this.preVote,
      checkQuorum: this.checkQuorum,
      tickIntervalMs: this.tickIntervalMs,
      debug: this.debug,
      workerApply: this.workerApply,
      workerStorage: this.workerStorage,
    });

    // Allow transport to discover us
    if (typeof this.transport.register === 'function') {
      this.transport.register(this);
    }

    // Start the node inside the worker
    await this._request('start', {});
    this._running = true;
  }

  async stop(opts = {}) {
    if (!this._worker) return;

    try {
      await this._request('stop', { drainApply: !!opts.drainApply, drainTicks: !!opts.drainTicks });
    } catch {
      // ignore
    }

    // Resolve all pending requests with an error
    for (const [id, p] of this._pending.entries()) {
      p.reject(new Error('Worker stopped'));
    }
    this._pending.clear();

    // Reject index/apply waiters
    this._rejectAllWaiters(new Error('Shutdown'));

    try {
      this._worker.off('message', this._onMessage);
      this._worker.off('error', this._onWorkerError);
      this._worker.off('exit', this._onWorkerExit);
    } catch {}
    try {
      await this._worker.terminate();
    } catch {}
    this._worker = null;
    this._running = false;
  }

  async status() {
    if (!this._running) return null;
    return await this._request('status', {});
  }

  async campaign() {
    if (!this._running) return;
    await this._request('campaign', {});
  }

  async propose(data) {
    if (!this._running) return;
    if (this._isApplying) {
      try { this.metrics?.onRejected && this.metrics.onRejected('Reentrancy'); } catch {}
      throw new RejectedError('Propose from apply() context is not allowed; use schedulePropose()', 'Reentrancy');
    }
    // Allow propose if leader hint points to self (status may lag briefly)
    const selfIsLeaderHint = this._lead && this._lead === this.id;
    if (this._role !== 'leader' && !selfIsLeaderHint) {
      const hint = this._lead ? { id: String(this._lead) } : undefined;
      try { this.metrics?.onRejected && this.metrics.onRejected('NotLeader', { term: this._term, leaderId: this._lead || null }); } catch {}
      throw new NotLeaderError(this._term, this._lead || null, hint);
    }

    // Normalize payload and use transfer list when possible
    let payload = { data: null };
    let transfer = [];

    if (data instanceof Uint8Array) {
      const viewCoversWholeBuffer = data.byteOffset === 0 && data.byteLength === data.buffer.byteLength;
      const buf = viewCoversWholeBuffer ? data.buffer : data.buffer.slice(data.byteOffset, data.byteOffset + data.byteLength);
      payload.data = buf;
      transfer = [buf];
    } else if (data instanceof ArrayBuffer) {
      payload.data = data;
      transfer = [data];
    } else if (typeof data === 'string') {
      payload.data = data;
    } else {
      throw new Error('propose(data) expects Uint8Array | ArrayBuffer | string');
    }

    await this._request('propose', payload, transfer);
    try { this.metrics?.onPropose && this.metrics.onPropose(); } catch {}
  }

  /**
   * Client-facing request helper with auto-forwarding and optional waits.
   * opts: { autoForward?: boolean=true, waitFor?: 'none'|'commit'|'apply'='none', timeout?: number, abortSignal?: AbortSignal }
   * Returns: { index, term }
   */
  async clientRequest(data, opts = {}) {
    if (!this._running) throw new Error('Not running');
    const autoForward = opts.autoForward !== false;
    const bypassLeadershipCheck = opts.autoForward === false; // transport->leader direct path should not gate on controller state
    const waitFor = opts.waitFor || 'none';
    const timeoutMs = opts.timeout;
    const abortSignal = opts.abortSignal;
    const manualMode = !this.tickIntervalMs || this.tickIntervalMs <= 0;

    // Treat self as leader if leaderId points to self (state may lag briefly)
    const selfIsLeaderHint = this._lead && this._lead === this.id;

    if (!bypassLeadershipCheck && this._role !== 'leader' && !selfIsLeaderHint) {
      const err = new NotLeaderError(this._term, this._lead || null, this._lead ? { id: String(this._lead) } : undefined);
      // Avoid forwarding loops: only forward if leaderId is known and not self
      if (autoForward && this._lead && this._lead !== this.id && this.transport && typeof this.transport.sendClientRequest === 'function') {
        const fwd = this.transport.sendClientRequest(this._lead, data, { autoForward: false, waitFor: 'commit', timeout: timeoutMs, abortSignal });
        const result = await this._withTimeout(fwd, timeoutMs, abortSignal);
        // Honor requested waitFor on this follower too (local apply/commit)
        if (!manualMode && result && typeof result.index === 'number') {
          if (waitFor === 'apply') {
            await this.waitForCommit(result.index, { localApply: true, timeout: timeoutMs, abortSignal });
          } else if (waitFor === 'commit') {
            await this.waitForCommit(result.index, { localApply: false, timeout: timeoutMs, abortSignal });
          }
        }
        return result;
      }
      // Best-effort stabilization: wait for leader and re-evaluate once
      try {
        await this._withTimeout(this.waitForLeader(timeoutMs), timeoutMs, abortSignal);
      } catch {}
      if (this._role !== 'leader' && !(this._lead && this._lead === this.id)) {
        try { this.metrics?.onRejected && this.metrics.onRejected('NotLeader', { term: this._term, leaderId: this._lead || null }); } catch {}
        throw err;
      }
      // fall through to leader path after stabilization
    }

    const before = Number(this._lastLogIndex) || 0;
    const drainP = manualMode ? null : this._awaitDrainOnce();
    // Propose directly to worker to avoid transient role lag causing NotLeaderError
    {
      let payload = { data: null };
      let transfer = [];
      if (data instanceof Uint8Array) {
        const viewCoversWholeBuffer = data.byteOffset === 0 && data.byteLength === data.buffer.byteLength;
        const buf = viewCoversWholeBuffer ? data.buffer : data.buffer.slice(data.byteOffset, data.byteOffset + data.byteLength);
        payload.data = buf;
        transfer = [buf];
      } else if (data instanceof ArrayBuffer) {
        payload.data = data;
        transfer = [data];
      } else if (typeof data === 'string') {
        payload.data = data;
      } else {
        throw new Error('clientRequest(data) expects Uint8Array | ArrayBuffer | string');
      }
      await this._request('propose', payload, transfer);
      try { this.metrics?.onPropose && this.metrics.onPropose(); } catch {}
    }

    // In manual tick mode, return immediately with best-effort index prediction
    if (manualMode) {
      const index = (Number.isFinite(before) ? before : 0) + 1;
      const term = Number(this._term);
      return { index, term };
    }

// Ensure worker drained Ready so lastLogIndex is updated
if (drainP) {
  await this._withTimeout(drainP, timeoutMs, abortSignal);
}

// Refresh status to avoid stale caches before computing index/term
let snap = null;
try { snap = await this.status(); } catch {}
const lastLog = snap && typeof snap.lastLogIndex === 'number' ? Number(snap.lastLogIndex) : Number(this._lastLogIndex);
const index = lastLog > before ? lastLog : (before + 1);
const term = snap && typeof snap.term === 'number' ? Number(snap.term) : Number(this._term);

    if (waitFor === 'commit') {
      await this.waitForCommit(index, { localApply: false, timeout: timeoutMs, abortSignal });
    } else if (waitFor === 'apply') {
      await this.waitForCommit(index, { localApply: true, timeout: timeoutMs, abortSignal });
    }

    return { index, term };
  }

  async schedulePropose(data, opts = {}) {
    return new Promise((resolve, reject) => {
      setImmediate(() => {
        this.clientRequest(data, opts).then(resolve, reject);
      });
    });
  }

  // Internal: central request/response
  _request(type, payload = {}, transferList = []) {
    if (!this._worker) throw new Error('Worker not started');
    const reqId = this._nextReqId++;
    const msg = { type, reqId, ...payload };

    return new Promise((resolve, reject) => {
      this._pending.set(reqId, { resolve, reject });
      try {
        this._worker.postMessage(msg, transferList);
      } catch (err) {
        this._pending.delete(reqId);
        reject(err);
      }
    });
  }

  // Send a one-way message to the worker (no response expected)
  _post(type, payload = {}, transferList = []) {
    if (!this._worker) return;
    const msg = { type, ...payload };
    this._worker.postMessage(msg, transferList);
  }

  // Worker message handler
  async _onMessage(msg) {
    const { type } = msg || {};
    if (!type) return;

    try {
      switch (type) {
        case 'response': {
          const { reqId, result, error } = msg;
          const pending = this._pending.get(reqId);
          if (!pending) break;
          this._pending.delete(reqId);
          if (error) pending.reject(new Error(error));
          else pending.resolve(result);
          break;
        }

        case 'outbound': {
          // Forward messages to transport on main thread
          const { msgs } = msg;
          if (msgs && msgs.length) {
            await this.transport.send(this.id, msgs);
          }
          break;
        }

        case 'applyCommitted': {
          const { reqId, entries } = msg;
          try {
            if (typeof this.apply !== 'function') {
              this._post('applyAck', { reqId, error: 'apply(entry) is not configured on the main thread' });
              break;
            }
            this._isApplying = true;
            let maxIdx = 0;
            if (entries && entries.length) {
              for (const e of entries) {
                const idx = Number(e && (e.index ?? e.idx));
                if (!Number.isNaN(idx) && idx > maxIdx) maxIdx = idx;
                await this.apply(e);
              }
            }
            // Opportunistically advance lastApplied to unblock localApply waiters
            if (maxIdx > 0) {
              try { this._handleStateUpdate({ lastApplied: maxIdx }); } catch {}
            }
            // Debug (controller): trace applyCommitted progress when enabled
            if (process?.env?.RAFT_DEBUG_CTRL === '1') {
              try {
                console.log(`[ctrl ${this.id}] applyCommitted entries=${(entries && entries.length) || 0} maxIdx=${maxIdx}`);
              } catch {}
            }
            // Ack success
            this._post('applyAck', { reqId });
            // Directly resolve waiters up to maxIdx to avoid depending solely on state updates
            if (maxIdx > 0) {
              // resolve apply waiters
              for (const w of Array.from(this._applyWaiters)) {
                if (Number(w.index) <= maxIdx) {
                  this._applyWaiters.delete(w);
                  try { w.resolve(); } catch {}
                }
              }
              // resolving commit waiters is safe when apply ≥ index (apply implies commit)
              for (const w of Array.from(this._commitWaiters)) {
                if (Number(w.index) <= maxIdx) {
                  this._commitWaiters.delete(w);
                  try { w.resolve(); } catch {}
                }
              }
            }
          } catch (err) {
            this._post('applyAck', { reqId, error: String(err && err.message ? err.message : err) });
          } finally {
            this._isApplying = false;
          }
          break;
        }

        case 'stateUpdate': {
          const { snapshot } = msg;
          this._handleStateUpdate(snapshot || {});
          break;
        }

        case 'drain': {
          // Ready queue drained in worker; re-check any waiters
          this._resolveIndexWaiters();
          // Increment residency ticks while leader
          if (this._role === 'leader') {
            this._termResidencyTicks++;
          }
          // Resolve any one-shot drain waiters
          if (this._drainWaiters && this._drainWaiters.size) {
            for (const resolve of Array.from(this._drainWaiters)) {
              this._drainWaiters.delete(resolve);
              try { resolve(); } catch {}
            }
          }
          break;
        }

        case 'commitAdvanced': {
          const { commitIndex, term } = msg;
          try { this._emitTo(this._commitAdvancedCbs, { commitIndex: Number(commitIndex) || 0, term: Number(term) || this._term }); } catch {}
          if (Number(commitIndex) > 0) {
            try { this._handleStateUpdate({ commitIndex: Number(commitIndex) }); } catch {}
          }
          break;
        }

        case 'quorumActive': {
          const { term, majorityAcks, quorumSize, leaderId } = msg;
          this._lastQuorumActiveTerm = Number(term) || this._lastQuorumActiveTerm;
          try {
            this._emitTo(this._quorumActiveCbs, {
              term: Number(term) || 0,
              majorityAcks: Number(majorityAcks) || 0,
              quorumSize: Number(quorumSize) || 0,
              leaderId: leaderId ? String(leaderId) : this.id,
            });
          } catch {}
          break;
        }

        case 'error': {
          // Worker reported an error condition (non-fatal)
          if (this.debug) {
            console.error('[ThreadedRaftNode worker error]', msg.message || msg);
          }
          break;
        }

        default: {
          if (this.debug) {
            console.warn('[ThreadedRaftNode] Unknown message from worker:', msg);
          }
        }
      }
    } catch (err) {
      const msg = String(err && (err.message || err));
      // Suppress expected shutdown noise, e.g. peers stopping concurrently
      if (!this._running || msg.includes('Worker stopped')) {
        return;
      }
      if (this.debug && process?.env?.RAFT_DEBUG_CTRL === '1') {
        console.error('[ThreadedRaftNode onMessage handler error]', err);
      }
    }
  }

  _onWorkerError(err) {
    // Bubble errors to all pending requests
    for (const [id, p] of this._pending.entries()) {
      p.reject(err);
    }
    this._pending.clear();
    // Reject any waiters waiting on indexes
    this._rejectAllWaiters(err);
    if (this.debug && process?.env?.RAFT_DEBUG_CTRL === '1') {
      console.error('[ThreadedRaftNode worker error]', err);
    }
  }

  _onWorkerExit(code) {
    const err = new Error(`Worker exited with code ${code}`);
    for (const [id, p] of this._pending.entries()) {
      p.reject(err);
    }
    this._pending.clear();
    this._worker = null;
    this._running = false;
    // Reject any pending commit/apply waiters
    this._rejectAllWaiters(err);
    if (this.debug && process?.env?.RAFT_DEBUG_CTRL === '1') {
      console.error('[ThreadedRaftNode worker exit]', code);
    }
  }

  // Event subscriptions
  onStateChange(cb) {
    if (typeof cb !== 'function') return () => {};
    this._stateChangeCbs.add(cb);
    return () => this._stateChangeCbs.delete(cb);
  }

  onBecameLeader(cb) {
    if (typeof cb !== 'function') return () => {};
    this._becameLeaderCbs.add(cb);
    return () => this._becameLeaderCbs.delete(cb);
  }

  onBecameFollower(cb) {
    if (typeof cb !== 'function') return () => {};
    this._becameFollowerCbs.add(cb);
    return () => this._becameFollowerCbs.delete(cb);
  }

  // New: granular event subscriptions
  onRoleChange(cb) {
    if (typeof cb !== 'function') return () => {};
    this._roleChangeCbs.add(cb);
    return () => this._roleChangeCbs.delete(cb);
  }

  onCommitAdvanced(cb) {
    if (typeof cb !== 'function') return () => {};
    this._commitAdvancedCbs.add(cb);
    return () => this._commitAdvancedCbs.delete(cb);
  }

  onQuorumActive(cb) {
    if (typeof cb !== 'function') return () => {};
    this._quorumActiveCbs.add(cb);
    return () => this._quorumActiveCbs.delete(cb);
  }

  // Waiting primitives
  async waitForLeader(timeoutMs) {
    if (!this._running) throw new Error('Not running');
    if (this._lead && this._role !== 'candidate') {
      return this._lead;
    }
    const p = new Promise((resolve) => {
      const off = this.onStateChange((s) => {
        if (s && s.lead && s.role !== 'candidate') {
          off();
          resolve(String(s.lead));
        }
      });
    });
    return this._withTimeout(p, timeoutMs);
  }

  async waitForCommit(index, opts = {}) {
    console.log(`[raft-worker-controller] waitForCommit start id=${this.id} index=${index} opts=${JSON.stringify(opts)}`);
    if (!this._running) throw new Error('Not running');
    const localApply = !!opts.localApply;
    const timeoutMs = opts.timeout;
    const abortSignal = opts.abortSignal;

    // Fast-path: already satisfied
    if (Number(this._commitIndex) >= Number(index)) {
      if (!localApply || Number(this._lastApplied) >= Number(index)) {
        return;
      }
    }

    const waits = [];

    // Commit waiter
    const commitP = new Promise((resolve, reject) => {
      const waiter = { index: Number(index), resolve, reject };
      this._commitWaiters.add(waiter);
      this._resolveIndexWaiters();
    });
    waits.push(commitP);

    // Optional local apply waiter
    if (localApply) {
      const applyP = new Promise((resolve, reject) => {
        const waiter = { index: Number(index), resolve, reject };
        this._applyWaiters.add(waiter);
        this._resolveIndexWaiters();
      });
      waits.push(applyP);
    }

    // Fallback: poll status to drive waiter resolution even if events are missed
    let poller = null;
    if (timeoutMs && timeoutMs > 0) {
      const tickMs = Number(this.tickIntervalMs || 100);
      const hb = Number(this.heartbeatTick || 1);
      const interval = Math.max(25, Math.min(200, hb * tickMs));
      poller = setInterval(async () => {
        try {
          const snap = await this.status();
          if (snap) this._handleStateUpdate(snap);
        } catch {}
      }, interval);
    }

    const all = Promise.all(waits).then(() => {
      console.log(`[raft-worker-controller] waitForCommit resolved id=${this.id} index=${index}`);
      return undefined;
    });
    const wrapped = all.finally(() => {
      if (poller) {
        try { clearInterval(poller); } catch {}
      }
    });
    return this._withTimeout(wrapped, timeoutMs, abortSignal).catch((err) => {
      console.warn(`[raft-worker-controller] waitForCommit timeout or error id=${this.id} index=${index} err=${err?.message}`);
      throw err;
    });
  }

  async barrier() {
    if (!this._running) return;
    if (this._role === 'leader') {
      const target = Number(this._lastLogIndex) || 0;
      if (target > 0) {
        await this.waitForCommit(target, { localApply: false });
      }
    } else {
      const target = Number(this._commitIndex) || 0;
      if (target > 0) {
        await this.waitForCommit(target, { localApply: true });
      }
    }
  }

  /**
   * Linearizable read (lease-based): leader-gated, requires stability window. Returns current commit index.
   */
  async readIndex(opts = {}) {
    if (!this._running) throw new Error('Not running');
    const timeoutMs = opts.timeout;
    const abortSignal = opts.abortSignal;
    const selfIsLeaderHint = this._lead && this._lead === this.id;

    if (this._role !== 'leader' && !selfIsLeaderHint) {
      const err = new NotLeaderError(this._term, this._lead || null, this._lead ? { id: String(this._lead) } : undefined);
      try { this.metrics?.onRejected && this.metrics.onRejected('NotLeader', { term: this._term, leaderId: this._lead || null }); } catch {}
      throw err;
    }
    await this._withTimeout(this._stableWindow(timeoutMs), timeoutMs, abortSignal);
    return Number(this._commitIndex) || 0;
  }

  // Deterministic testing helpers
  async manualTick() { if (!this._running) return; await this._request('manualTick', {}); }
  async advanceTicks(n = 1) { if (!this._running) return; await this._request('advanceTicks', { n: Number(n) || 0 }); }

  /**
   * Transfer leadership to a target peer by stepping a MsgTransferLeader locally.
   * Resolves when the target is the stable leader (or rejects on timeout).
   */
  async transferLeadership(targetId, timeoutMs) {
    if (!this._running) throw new Error('Not running');
    const tid = String(targetId);
    // Request transfer by sending MsgTransferLeader from transferee (tid) to the current leader (self).
    const msg = { from: String(tid), to: String(this.id), msgType: 13 };
    await this._request('step', { message: msg });

    // wait until leader is target, then for stability window
    await this._withTimeout(this._waitForLeadId(tid), timeoutMs);
    await this._stableWindow(timeoutMs);
  }

  /**
   * Step down from leadership by triggering an immediate election (MsgTimeoutNow).
   * Resolves when this node is no longer leader; if already follower, resolves immediately.
   */
  async stepDown(timeoutMs) {
    if (!this._running) throw new Error('Not running');
    if (this._role !== 'leader' || (this._lead && this._lead !== this.id)) return;

    // Choose a transferee (any peer that's not self) and transfer leadership
    const candidates = Array.isArray(this.peers) ? this.peers.map(String).filter((pid) => pid !== this.id) : [];
    if (!candidates.length) return; // single-node cluster: nothing to do

    const target = candidates[0];
    const manualMode = !this.tickIntervalMs || this.tickIntervalMs <= 0;
    if (manualMode) {
      // In manual tick mode:
      // 1) Ask current leader (self) to transfer leadership to target (transferee) by stepping TL on leader (from=target -> to=self)
      // 2) Nudge the target to campaign via MsgTimeoutNow to accelerate the handoff
      const m13 = { from: String(target), to: String(this.id), msgType: 13 };
      await this._request('step', { message: m13 });
      const m14 = { from: String(this.id), to: String(target), msgType: 14 };
      if (this.transport && typeof this.transport.send === 'function') {
        await this.transport.send(this.id, [m14]);
      } else {
        await this._request('step', { message: m14 });
      }
      return;
    }
    await this.transferLeadership(target, timeoutMs);
  }

  /**
   * Proactively trigger heartbeats to accelerate quorum acquisition after becoming leader.
   */
  async sendHeartbeat() {
    if (!this._running) return;
    // Step a MsgBeat (1) to self; causes leader to emit heartbeats
    const msg = { from: String(this.id), to: String(this.id), msgType: 1 };
    try { await this._request('step', { message: msg }); } catch {}
  }

  /**
   * Event-driven waiter: resolves when this node is leader and, if required, has obtained quorum in the current term.
   * options: { requireQuorum = true, minTermResidencyTicks = 0, signal?: AbortSignal }
   * Note: minTermResidencyTicks is driven by Ready drains (no wall-clock sleeps).
   */
  async waitForLeaderStable(options = {}) {
    if (!this._running) throw new Error('Not running');
    const requireQuorum = options.requireQuorum !== false;
    const minTicks = Number(options.minTermResidencyTicks || 0);
    const signal = options.signal;

    const satisfied = () => {
      const isLeader = this._role === 'leader' || (this._lead && this._lead === this.id);
      const quorumOk = !requireQuorum || (this._lastQuorumActiveTerm === this._term);
      const ticksOk = this._termResidencyTicks >= minTicks;
      return isLeader && quorumOk && ticksOk;
    };

    // Fast path
    if (satisfied()) return;

    return this._withTimeout(new Promise((resolve, reject) => {
      let offRole = () => {};
      let offQuorum = () => {};
      // Re-check on drain ticks if residency required
      const onDrainTick = () => {
        if (satisfied()) {
          cleanup();
          resolve();
        }
      };
      const cleanup = () => {
        try { offRole(); offQuorum(); } catch {}
      };

      offRole = this.onRoleChange((rc) => {
        if (rc && rc.role === 'leader') {
          this._termResidencyTicks = 0;
          this.sendHeartbeat().catch(() => {});
        } else {
          this._termResidencyTicks = 0;
        }
        if (satisfied()) {
          cleanup();
          resolve();
        }
      });

      offQuorum = this.onQuorumActive((_evt) => {
        if (satisfied()) {
          cleanup();
          resolve();
        }
      });

      // If residency ticks required, piggyback on drain notifications for progress
      if (minTicks > 0) {
        const poll = () => setImmediate(onDrainTick);
        // Use drain waiters as a cheap way to get notified after readies progress
        const schedule = () => {
          try {
            const p = this._awaitDrainOnce();
            p.then(() => { onDrainTick(); schedule(); }).catch(() => {});
          } catch { /* ignore */ }
        };
        schedule();
      }

      if (signal) {
        const onAbort = () => { cleanup(); reject(Object.assign(new Error('Operation aborted'), { code: 'AbortError' })); };
        if (signal.aborted) return onAbort();
        signal.addEventListener('abort', onAbort, { once: true });
      }
    }), undefined, signal);
  }

  /**
   * Wait until a stable leader exists using the new event-driven waiter.
   */
  async runUntilStableLeader(timeoutMs) {
    const leaderId = await this.waitForLeader(timeoutMs);
    await this._stableWindow(timeoutMs);
    return leaderId;
  }

  // Internals
  _waitForLeadId(targetId) {
    const tid = String(targetId);
    if (this._lead && String(this._lead) === tid) return Promise.resolve();
    return new Promise((resolve) => {
      const off = this.onStateChange((s) => {
        if (s && s.lead && String(s.lead) === tid) {
          off();
          resolve();
        }
      });
    });
  }

  _stableWindow(timeoutMs) {
    // consider two heartbeat periods as stability window
    const hb = Number(this.heartbeatTick || 1);
    const tickMs = Number(this.tickIntervalMs || 100);
    const windowMs = Math.max(1, hb) * tickMs * 2;

    return this._withTimeout(new Promise((resolve) => {
      let lastChange = Date.now();
      const off = this.onStateChange(() => { lastChange = Date.now(); });
      const check = () => {
        if (Date.now() - lastChange >= windowMs) {
          off();
          resolve();
        } else {
          setTimeout(check, Math.min(50, Math.max(10, windowMs / 10)));
        }
      };
      setTimeout(check, windowMs);
    }), timeoutMs);
  }

  _handleStateUpdate(snapshot) {
    const prev = {
      role: this._role,
      term: this._term,
      lead: this._lead,
      commitIndex: this._commitIndex,
      lastApplied: this._lastApplied,
      lastLogIndex: this._lastLogIndex,
    };

    const role = snapshot && snapshot.role ? String(snapshot.role) : prev.role;
    const term = snapshot && snapshot.term != null ? Number(snapshot.term) : prev.term;
    const lead = snapshot && snapshot.lead != null && snapshot.lead !== '0' && snapshot.lead !== 0
      ? String(snapshot.lead) : (snapshot && (snapshot.lead === '0' || snapshot.lead === 0) ? null : prev.lead);
    const commitIndex = snapshot && snapshot.commitIndex != null ? Number(snapshot.commitIndex) : prev.commitIndex;
    const lastApplied = snapshot && snapshot.lastApplied != null ? Number(snapshot.lastApplied) : prev.lastApplied;
    const lastLogIndex = snapshot && snapshot.lastLogIndex != null ? Number(snapshot.lastLogIndex) : prev.lastLogIndex;

    const changed =
      role !== prev.role ||
      term !== prev.term ||
      lead !== prev.lead ||
      commitIndex !== prev.commitIndex ||
      lastApplied !== prev.lastApplied ||
      lastLogIndex !== prev.lastLogIndex;

    this._role = role;
    this._term = term;
    this._lead = lead;
    this._commitIndex = commitIndex;
    this._lastApplied = lastApplied;
    this._lastLogIndex = lastLogIndex;

    if (changed) {
      if (prev.role !== role) {
        try { this.metrics && typeof this.metrics.onRoleChange === 'function' && this.metrics.onRoleChange(prev.role, role); } catch {}
        if (role === 'leader') {
          this._emitTo(this._becameLeaderCbs, { term: this._term });
          this._termResidencyTicks = 0;
        } else if (role === 'follower') {
          this._emitTo(this._becameFollowerCbs, { term: this._term, lead: this._lead || null });
          this._termResidencyTicks = 0;
        } else {
          this._termResidencyTicks = 0;
        }
        // Emit dedicated roleChange notification
        this._emitTo(this._roleChangeCbs, { role: this._role, term: this._term, lead: this._lead || null });
      }
      this._emitTo(this._stateChangeCbs, {
        role: this._role,
        term: this._term,
        lead: this._lead,
        commitIndex: this._commitIndex,
        lastApplied: this._lastApplied,
        lastLogIndex: this._lastLogIndex,
      });
    }

    // Debug (controller): trace state updates when enabled
    if (process?.env?.RAFT_DEBUG_CTRL === '1') {
      try {
        console.log(`[ctrl ${this.id}] state role=${this._role} term=${this._term} lead=${this._lead} commit=${this._commitIndex} applied=${this._lastApplied} lastLog=${this._lastLogIndex}`);
      } catch {}
    }

    this._resolveIndexWaiters();
  }

  _emitTo(set, payload) {
    for (const cb of Array.from(set)) {
      try { cb(payload); } catch {}
    }
  }

  _resolveIndexWaiters() {
    for (const w of Array.from(this._commitWaiters)) {
      if (Number(this._commitIndex) >= Number(w.index)) {
        this._commitWaiters.delete(w);
        try { w.resolve(); } catch {}
      }
    }
    for (const w of Array.from(this._applyWaiters)) {
      if (Number(this._lastApplied) >= Number(w.index)) {
        this._applyWaiters.delete(w);
        try { w.resolve(); } catch {}
      }
    }
  }

  _awaitDrainOnce() {
    return new Promise((resolve) => {
      this._drainWaiters.add(resolve);
    });
  }

  _rejectAllWaiters(err) {
    for (const w of Array.from(this._commitWaiters)) {
      this._commitWaiters.delete(w);
      try { w.reject(err); } catch {}
    }
    for (const w of Array.from(this._applyWaiters)) {
      this._applyWaiters.delete(w);
      try { w.reject(err); } catch {}
    }
  }

  _withTimeout(p, timeoutMs, abortSignal) {
    if (!timeoutMs && !abortSignal) return p;
    return new Promise((resolve, reject) => {
      let settled = false;
      let to = null;
      const onAbort = () => {
        if (settled) return;
        settled = true;
        reject(Object.assign(new Error('Operation aborted'), { code: 'AbortError' }));
      };
      if (timeoutMs && timeoutMs > 0) {
        to = setTimeout(() => {
          if (settled) return;
          settled = true;
          reject(Object.assign(new Error('Operation timed out'), { code: 'Timeout' }));
        }, timeoutMs);
      }
      if (abortSignal) {
        if (abortSignal.aborted) {
          onAbort();
          return;
        }
        abortSignal.addEventListener('abort', onAbort, { once: true });
      }
      p.then((v) => {
        if (settled) return;
        settled = true;
        if (to) clearTimeout(to);
        if (abortSignal) abortSignal.removeEventListener('abort', onAbort);
        resolve(v);
      }, (err) => {
        if (settled) return;
        settled = true;
        if (to) clearTimeout(to);
        if (abortSignal) abortSignal.removeEventListener('abort', onAbort);
        reject(err);
      });
    });
  }
}
